async function waitFor(check, timeoutMs, intervalMs) {
  // Your code here
}

coding.solution:
async function waitFor(check, timeoutMs, intervalMs) {
  const deadline = Date.now() + timeoutMs;
  while (true) {
    const value = await check();
    if (value) return value;
    if (Date.now() + intervalMs > deadline) throw new Error(`Timed out after ${timeoutMs} ms`);
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}

tests.code:
let n = 0;
const v = await waitFor(async () => (++n >= 3 ? 'reserved' : null), 1000, 10);
assertEqual(v, 'reserved');
assertEqual(n, 3);

let msg = '';
try { await waitFor(async () => false, 100, 20); } catch (e) { msg = e.message; }
assert(msg.startsWith('Timed out'), 'expected a timeout error, got: ' + msg);

