coding.solution:
class StockConsumer:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.processed = set()

    def handle(self, message):
        if message['id'] in self.processed:
            return 'duplicate'
        new_qty = self.stock.get(message['sku'], 0) - message['qty']
        if new_qty < 0:
            raise ValueError('insufficient stock')
        self.stock[message['sku']] = new_qty
        self.processed.add(message['id'])
        return 'processed'

tests.code:
c = StockConsumer({'A': 1})
m = {'id': 'm2', 'sku': 'A', 'qty': 2}
try:
    c.handle(m)
    raise AssertionError('expected ValueError')
except ValueError:
    pass
c.stock['A'] = 4
assert c.handle(m) == 'processed' and c.stock == {'A': 2}
